	@Test
	void independentJoinKeepsTwoEqualGroupMappings() {
		try (Fixture fixture = new Fixture()) {
			Join genericJoin = new Join(singleValue("g", A), projectedGroup(false));
			Join nativeJoin = new Join(singleValue("g", A), projectedGroup(false));
			Group nativeGroup = (Group) nativeJoin.getRightArg();
			assertThat(TupleExprs.requiresIndependentEvaluation(genericJoin.getRightArg())).isTrue();
			Map<String, Value> expected = Map.of("g", A, "n", integer(1));
			QueryEvaluationStep genericStep = fixture.generic.precompile(genericJoin, fixture.context);
			assertThat(rows(genericStep, EmptyBindingSet.getInstance()))
					.as("generic independent Join retains both Group mappings")
					.containsExactlyInAnyOrder(expected, expected);
			enableTelemetry(nativeJoin, nativeGroup);
			QueryEvaluationStep nativeStep = fixture.nativeStrategy.precompile(nativeJoin, fixture.context);
			Observation actual = observe(nativeStep, nativeJoin, nativeGroup, EmptyBindingSet.getInstance());
			assertThat(actual.rows()).as("native-strategy Join retains both Group mappings")
					.containsExactlyInAnyOrder(expected, expected);
			System.out.printf("projected-group-independent-join observed=%s%n", actual);
		}
	}

	private static List<Map<String, Value>> expectedGroup(String input, boolean duplicate) {
		Map<String, Value> bound = Map.of("g", A, "n", integer(duplicate ? 2 : 1));
		if (input.equals("absent")) {
			return List.of(bound, Map.of("n", integer(1)));
		}
		if (input.equals("b")) {
			return List.of(bound, Map.of("g", B, "n", integer(1)));
		}
		return duplicate ? List.of(bound, Map.of("g", A, "n", integer(1))) : List.of(bound);
	}

	private static Group projectedGroup(boolean duplicate) {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setDeclaredBindingNames(Set.of("h"));
		values.setBindingSets(duplicate
				? List.of(binding("h", A), binding("h", A), EmptyBindingSet.getInstance())
				: List.of(binding("h", A), EmptyBindingSet.getInstance()));
		Projection projection = new Projection(values, new ProjectionElemList(new ProjectionElem("h", "g")), true);
		Group group = new Group(projection, List.of("g"));
		group.addGroupElement(new GroupElem("n", new Count(null)));
		return group;
	}

	private static Group projectedNonKeyCount() {
		BindingSetAssignment values = valuesWithUndef("h");
		Projection projection = new Projection(values, new ProjectionElemList(new ProjectionElem("h", "x")), true);
		Group group = new Group(projection);
		group.addGroupElement(new GroupElem("n", new Count(Var.of("x"), false)));
		return group;
	}

	private static Group ordinaryValuesCount() {
		Group group = new Group(valuesWithUndef("x"));
		group.addGroupElement(new GroupElem("n", new Count(Var.of("x"), false)));
		return group;
	}

	private static BindingSetAssignment valuesWithUndef(String name) {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setDeclaredBindingNames(Set.of(name));
		values.setBindingSets(List.of(binding(name, A), EmptyBindingSet.getInstance()));
		return values;
	}

	private static BindingSetAssignment singleValue(String name, Value value) {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setDeclaredBindingNames(Set.of(name));
		values.setBindingSets(List.of(binding(name, value)));
		return values;
	}

	private static MapBindingSet binding(String name, Value value) {
		MapBindingSet result = new MapBindingSet();
		result.addBinding(name, value);
		return result;
	}

	private static Value integer(int value) {
		return VF.createLiteral(Integer.toString(value), XSD.INTEGER);
	}

	private static void enableTelemetry(TupleExpr root, Group group) {
		root.setRuntimeTelemetryEnabled(true);
		root.setExecutionSummaryEnabled(true);
		group.setRuntimeTelemetryEnabled(true);
		group.setExecutionSummaryEnabled(true);
	}

	private static Observation observe(QueryEvaluationStep step, TupleExpr root, Group group, BindingSet input) {
		root.setStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH, null);
		root.setStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN, null);
		group.setStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH, null);
		group.setStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN, null);
		long before = count(group);
		List<Map<String, Value>> result = rows(step, input);
		return new Observation(result, count(group) - before,
				root.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH),
				group.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH),
				root.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN),
				group.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN), step.getClass().getName());
	}

	private static BindingObservation observeBindings(QueryEvaluationStep step, TupleExpr root, Group group,
			BindingSet input) {
		root.setStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH, null);
		root.setStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN, null);
		group.setStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH, null);
		group.setStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN, null);
		long before = count(group);
		List<BindingSet> result = bindingRows(step, input);
		return new BindingObservation(result, count(group) - before,
				root.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH),
				group.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH),
				group.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN));
	}

	private static List<BindingSet> bindingRows(QueryEvaluationStep step, BindingSet input) {
		List<BindingSet> results = new ArrayList<>();
		try (var rows = step.evaluate(input)) {
			while (rows.hasNext()) {
				results.add(rows.next());
			}
		}
		return List.copyOf(results);
	}

	private static List<Map<String, Value>> bindingMaps(List<BindingSet> bindings) {
		List<Map<String, Value>> results = new ArrayList<>();
		for (BindingSet bindingSet : bindings) {
			Map<String, Value> row = new HashMap<>();
			bindingSet.forEach(binding -> row.put(binding.getName(), binding.getValue()));
			results.add(Map.copyOf(row));
		}
		return List.copyOf(results);
	}

	private static void assertNonKeyAuthority(BindingSet result, String name) {
		if (name.equals("probe-only-a")) {
			assertThat(result.getValue("x")).isNull();
			assertThat(BindingFrameBindings.probeValue(result, "x")).isEqualTo(A);
			assertThat(GraphFrameBindings.isSupplied(result, "x")).isFalse();
		} else if (name.equals("supplied-graph-a")) {
			assertThat(GraphFrameBindings.isSupplied(result, "x")).isTrue();
		} else if (name.equals("empty-marker") || name.equals("marked-visible-a")) {
			assertThat(BindingFrameBindings.substitutionDomain(result)).isEmpty();
		}
	}

	private static void assertNonKeyAuthority(SoftAssertions softly, BindingSet result, String name) {
		if (name.equals("probe-only-a")) {
			softly.assertThat(result.getValue("x")).isNull();
			softly.assertThat(BindingFrameBindings.probeValue(result, "x")).isEqualTo(A);
			softly.assertThat(GraphFrameBindings.isSupplied(result, "x")).isFalse();
		} else if (name.equals("supplied-graph-a")) {
			softly.assertThat(GraphFrameBindings.isSupplied(result, "x")).isTrue();
		} else if (name.equals("empty-marker") || name.equals("marked-visible-a")) {
			softly.assertThat(BindingFrameBindings.substitutionDomain(result)).isEmpty();
		}
	}

	private static List<Map<String, Value>> rows(QueryEvaluationStep step, BindingSet input) {
		List<Map<String, Value>> rows = new ArrayList<>();
		try (var iteration = step.evaluate(input)) {
			while (iteration.hasNext()) {
				Map<String, Value> row = new HashMap<>();
				iteration.next().forEach(binding -> row.put(binding.getName(), binding.getValue()));
				rows.add(Map.copyOf(row));
			}
		}
		return List.copyOf(rows);
	}

	private static long count(QueryModelNode node) {
		return Math.max(0L, node.getLongMetricActual("nativeInvocationsActual"));
	}

	private static boolean fallback(String path) {
		return path != null && path.contains("genericFallback(");
	}

	private final class Fixture implements AutoCloseable {
		private final LmdbStore store;
		private final SailRepository repository;
		private final SailDataset dataset;
		private final EvaluationStrategy generic;
		private final EvaluationStrategy nativeStrategy;
		private final QueryEvaluationContext context = new QueryEvaluationContext.Minimal(null);

		private Fixture() {
			this(false);
		}

		private Fixture(boolean includeB) {
			store = new LmdbStore(directory.resolve("projected-group-attribution").toFile(),
					new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true));
			repository = new SailRepository(store);
			repository.init();
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.add(A, P, A);
				if (includeB) {
					connection.add(B, P, B);
				}
			}
			dataset = NativeQuerySourceAccess.openExplicitDataset(store);
			SailDatasetTripleTermSource source = new SailDatasetTripleTermSource(repository.getValueFactory(), dataset);
			EvaluationStatistics statistics = store.getSailStore().getEvaluationStatistics();
			generic = new DefaultEvaluationStrategy(source, null);
			nativeStrategy = new LmdbNativeEvaluationStrategyFactory(null)
					.createEvaluationStrategy(null, source, statistics, store.getQueryExecutionPolicy());
		}

		@Override
		public void close() {
			try {
				dataset.close();
			} finally {
				repository.shutDown();
			}
		}
	}
